mapper.select:
SELECT ca.id, ca.source_scheme_id, ca.teaching_task_id, c.id AS course_id, c.name AS course_name, pt.id AS teacher_id, CONCAT_WS('、', pt.name, CASE WHEN ast.id != pt.id THEN ast.name END) AS teacher_name, cr.id AS classroom_id, cr.name AS classroom_name, ts.id AS time_slot_id, ts.label AS time_slot_label, ts.week_number, ts.day_of_week, ts.period_index, ca.consecutive_slots, ca.status, (SELECT GROUP_CONCAT(cg.name ORDER BY cg.id SEPARATOR ', ') FROM teaching_task_class_group ttcg JOIN class_group cg ON ttcg.class_group_id = cg.id WHERE ttcg.teaching_task_id = tt.id) AS class_group_name, (SELECT ttcg.class_group_id FROM teaching_task_class_group ttcg WHERE ttcg.teaching_task_id = tt.id LIMIT 1) AS class_group_id FROM course_assignment ca JOIN teaching_task tt ON ca.teaching_task_id = tt.id JOIN course c ON tt.course_id = c.id JOIN teacher pt ON tt.primary_teacher_id = pt.id LEFT JOIN teacher ast ON tt.assistant_teacher_id = ast.id JOIN classroom cr ON ca.classroom_id = cr.id JOIN time_slot ts ON ca.time_slot_id = ts.id WHERE 1 = 1
AND (tt.primary_teacher_id = #{teacherId} OR tt.assistant_teacher_id = #{teacherId})
AND EXISTS ( SELECT 1 FROM teaching_task_class_group ttcg2 WHERE ttcg2.teaching_task_id = tt.id AND ttcg2.class_group_id = #{classGroupId} )
AND tt.course_id = #{courseId}
AND ca.classroom_id = #{classroomId}
AND ts.week_number = #{weekNumber}
AND ts.day_of_week = #{dayOfWeek}
AND ca.status = #{status}
ORDER BY ts.week_number ASC, ts.day_of_week ASC, ts.period_index ASC, ca.id ASC

        SELECT ca.id, ca.source_scheme_id, ca.teaching_task_id,
               ca.classroom_id, ca.time_slot_id, ca.consecutive_slots, ca.status, ca.created_at, ca.updated_at
        FROM course_assignment ca
        LEFT JOIN time_slot ts ON ca.time_slot_id = ts.id
        JOIN teaching_task tt ON ca.teaching_task_id = tt.id
        WHERE 1 = 1

		  AND (tt.primary_teacher_id = #{teacherId} OR tt.assistant_teacher_id = #{teacherId})


          AND EXISTS (
            SELECT 1 FROM teaching_task_class_group ttcg
            WHERE ttcg.teaching_task_id = tt.id AND ttcg.class_group_id = #{classGroupId}
          )


		  AND tt.course_id = #{courseId}


		  AND ca.classroom_id = #{classroomId}


          AND ca.status = #{status}


          AND ts.week_number = #{weekNumber}

        ORDER BY ca.id DESC
